#include <bits/stdc++.h>
using namespace std;

using ull = unsigned long long;

ull getFactorization(ull x) {
    if (x <= 1) return x + 1;

    const ull original = x;
    ull answer = original + 1;

    if (x % 2 == 0) {
        answer = min(answer, 2 + original / 2);
        while (x % 2 == 0) x /= 2;
    }

    for (ull p = 3; p <= x / p; p += 2) {
        if (x % p == 0) {
            answer = min(answer, p + original / p);
            while (x % p == 0) x /= p;
        }
    }

    if (x > 1) {
        answer = min(answer, x + original / x);
    }

    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ull n;
    cin >> n;

    if (n == 0) {
        cout << 0 << '\n';
        return 0;
    }

    cout << min({getFactorization(n),
                 getFactorization(n + 1),
                 getFactorization(n + 2)}) << '\n';

    return 0;
}

